{
 $args = func_get_args();
 foreach ($args as $k => $v)
 { 
 echo "arg".($k+1).": $vn"; 
 }
}
foo();
/* will print nothing */

foo("Hello");
/* will print Hello */

foo("Hello","World","Bye");
/* will print Hello World Bye */
?>

